package com.oyuki.marketsquare.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; @Entity @Table(name="markets") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class Market { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="lga_id") private LocalGovernment lga; @Column(nullable=false,length=180) private String name; @Column(length=500) private String address; @Column(length=500) private String categories; private BigDecimal latitude; private BigDecimal longitude; @Column(nullable=false) @Builder.Default private boolean active=true; }